import random
import math
from fractions import Fraction

def generate_disjointness_instance(n):
    variables = list(range(1, n + 1))
    clauses = []
    for i in range(n):
        clause = [random.choice(variables) for _ in range(2)]
        clauses.append(clause)
    return clauses

def compute_minimal_rank(A):
    n = len(A)
    rank = 0
    while True:
        found = False
        for i in range(n):
            for j in range(i + 1, n):
                if any(a in A[i] and b in A[j] for a, b in zip(A[i], A[j])):
                    found = True
                    break
            if found:
                break
        if not found:
            rank += 1
        else:
            return rank

def run_trial(seed: int) -> dict:
    random.seed(seed)
    n_values = [5, 10, 15, 20, 30, 40]
    ranks = []

    for n in n_values:
        instance = generate_disjointness_instance(n)
        rank = compute_minimal_rank(instance)
        ranks.append(rank)

    mean_rank = sum(ranks) / len(ranks)
    std_dev = math.sqrt(sum((x - mean_rank) ** 2 for x in ranks) / len(ranks))

    return {
        "metric_name": "minimal_rank",
        "metric_value": mean_rank,
        "instances_tested": len(n_values),
        "conjecture_holds": mean_rank > n_values[0] * math.log(n_values[0]) / 2,
        "counterexample": ""
    }

if __name__ == "__main__":
